('oppo-enco-buds2', 'shopee', 'https://shopee.ph/search/?keyword=oppo+enco+buds2+philippines&mmp_pid=an_13266010000&uls_trackid=56o91j3501jb&utm_campaign=id_Dx9rx8QG8L&utm_content=308137-01a0e5a7fb187c36be8cb394fa01bccd--103880-....&utm_medium=affiliates&utm_source=an_13266010000&utm_term=fmaahowwyq4s', 'https://invl.me/clnhvt0', 'OPPO Enco Buds2'),
('hanabishi-hraf-28s-3l-air-fryer', 'shopee', 'https://shopee.ph/search/?keyword=hanabishi+air+fryer+philippines&mmp_pid=an_13266010000&uls_trackid=56o91j5401lt&utm_campaign=id_104WvYQ3fjZ&utm_content=308137-01a0e5a7fd3a7c45b8ba41febb24a35c--103880-....&utm_medium=affiliates&utm_source=an_13266010000&utm_term=fmaahqmz81u1', 'https://invl.me/clnhvkh', 'Hanabishi HRAF-28S 3L Air Fryer')
) as batch(slug, merchant_slug, canonical_url, affiliate_url, title)
join "thebudolfinds".products product on product.slug=batch.slug
join "thebudolfinds".merchants merchant on merchant.slug=batch.merchant_slug
on conflict (merchant_id, external_id) do update set canonical_url=excluded.canonical_url, affiliate_url=excluded.affiliate_url, affiliate_network=excluded.affiliate_network, affiliate_status=excluded.affiliate_status, title=excluded.title, source_updated_at=now(), affiliate_generated_at=now(), updated_at=now();

insert into "thebudolfinds".homepage_feed_items (product_id, collection, collection_title, editorial_blurb, badge, collection_order, sort_order, is_active)
select product.id, batch.collection, batch.collection_title, batch.editorial_blurb, batch.badge, coalesce(feed.max_order,0)+row_number() over(partition by batch.collection order by batch.batch_order), batch.batch_order, true
from (values
('kyowa-kw-3820-air-fryer', 'home', 'Home', 'Kyowa''s 4-liter air fryer adds a digital display and preset cooking programs over the Hanabishi analog formula — the step-up for Filipino families who want digital control and multiple cooking modes without crossing the ₱2,000 price barrier.', 'Home pick', 1),
('xiaomi-mi-air-purifier-4-compact', 'home', 'Home', 'The best budget air purifier for Philippine condo bedrooms — Xiaomi''s compact model delivers True HEPA filtration with a real-time AQI display and Mi Home app control at the most accessible price point among certified HEPA air purifiers in the Philippine market.', 'Home pick', 2),
('xiaomi-smart-air-purifier-4-compact', 'home', 'Home', 'The best overall under-₱5,000 pick when sale pricing is available because it balances known specs, small-room coverage, app ecosystem, and filter availability.', 'Home pick', 3),
('dream-mate-micro-coral-fleece-blanket-50x60in', 'latest-finds', 'Latest finds', 'The cheapest soft blanket pick for sofa use, kids, dorms, and extra rainy-day layers.', 'Editor pick', 4),
('tecno-spark-go-2', 'latest-finds', 'Latest finds', 'The aggressive low-price pick for buyers who need a working Android phone and want maximum value below the ceiling.', 'Editor pick', 5),
('xiaomi-mi-led-desk-lamp-1s', 'for-your-desk', 'For your desk', 'The best overall student desk lamp if the budget allows: clean design, adjustable brightness, adjustable color temperature, and a better long-study experience than basic USB lamps.', 'Desk pick', 6),
('kyowa-kw-3916-electric-grill', 'latest-finds', 'Latest finds', 'Kyowa''s electric grill steps up from the Hanabishi entry with a larger grilling surface, temperature control dial, and slightly better non-stick construction — the recommended budget upgrade for Filipino households grilling multiple servings per session.', 'Editor pick', 7),
('imarflex-2-burner-electric-stove', 'latest-finds', 'Latest finds', 'The best overall electric stove for Filipino households cooking multiple dishes — Imarflex''s 2-burner electric stove provides the simultaneous dual cooking surface essential for Filipino meal preparation (rice + viand, soup + main, two dishes for family of four) at mid-range pricing.', 'Editor pick', 8),
('panasonic-wce8204-power-strip-with-surge-protector', 'latest-finds', 'Latest finds', 'The best surge-protected extension cord for the Philippines — Panasonic''s WCE series provides genuine joule-rated surge protection critical for Philippine power fluctuations, with the most trusted brand name in Philippine electrical products.', 'Editor pick', 9),
('nitecore-nu25-headlamp', 'for-your-desk', 'For your desk', 'The best lightweight rechargeable headlamp for people who want a compact, brighter, more outdoor-capable option.', 'Desk pick', 10),
('onikuma-k9-gaming-headset', 'latest-finds', 'Latest finds', 'The best gaming headset under ₱900 for mobile Filipino gamers — Onikuma K9''s 3.5mm compatibility, RGB lighting, and bass-forward audio profile make it the popular choice for Mobile Legends and Free Fire players on Android and iOS.', 'Editor pick', 11),
('imarflex-ifs-318k-ceramic-flat-iron', 'home', 'Home', 'The best budget-tier hair straightener from a recognized Philippine local brand — Imarflex''s ceramic flat iron does the basic job for occasional weekend use and students on tight budgets, with enough plate size for shoulder-length Filipino hair.', 'Home pick', 12),
('philips-hr3705-hand-mixer', 'latest-finds', 'Latest finds', 'The best premium hand mixer in the Philippines — Philips HR3705 combines 270W of motor power with QuickFix bowl guidance, turbo function, and the silent smooth Philips motor quality.', 'Editor pick', 13),
('sikatop-107-seal-ph', 'home', 'Home', 'A pre-dosed, two-component cementitious mortar listed for wet rooms, balconies, terraces, and other concrete/cementitious surfaces.', 'Home pick', 14),
('imarflex-imc-4500-4-5l-12-in-1-multicooker', 'latest-finds', 'Latest finds', 'The best larger electric cooker here for families that want plug-in cooking without buying a separate induction cooker.', 'Editor pick', 15),
('targus-classic-15-6-inch-laptop-backpack', 'gifts-that-dont-feel-generic', 'Gifts that don’t feel generic', 'The best overall laptop bag under ₱1,500 for the Philippines — Targus is the most trusted laptop bag brand at Philippine computer retailers, with the Classic Backpack providing genuine padded protection, organizational compartments, and brand reliability that makes it the default recommendation for Filipino students and office workers.', 'Giftable', 16),
('sharp-r-200gh-solo-microwave', 'latest-finds', 'Latest finds', 'Sharp''s most accessible solo microwave brings Japanese brand reliability to the mid-budget tier — 800W, 20L, and the Sharp name that Filipino households have trusted for appliances since the 1980s.', 'Editor pick', 17),
('aspectek-40w-indoor-bug-zapper', 'latest-finds', 'Latest finds', 'The best chemical-free mosquito killer for Filipino households that want insect control without chemicals — Aspectek''s UV light attracts and electrocutes mosquitoes and flying insects without insecticide, making it genuinely safe for households with young children, pets, and chemical sensitivities.', 'Editor pick', 18),
('tefal-cook-n-clean-nonstick-frypan', 'latest-finds', 'Latest finds', 'The safest brand-first nonstick pan choice for most homes, especially if you want Tefal''s heat indicator and familiar cookware reputation.', 'Editor pick', 19),
('anker-a3102-soundcore-mini-bluetooth-speaker', 'latest-finds', 'Latest finds', 'The best budget portable speaker for Filipino buyers — Anker''s Soundcore Mini delivers genuine Anker build quality, 15-hour battery, and surprising sound output at ₱700–₱1,200, making it the most trustworthy speaker at the lowest reputable-brand price point.', 'Editor pick', 20),
('aukey-pb-y36-power-bank', 'latest-finds', 'Latest finds', 'The best entry-level fast-charging power bank for Filipino commuters — 10,000mAh with 18W Quick Charge output that charges modern Android phones in under 2 hours, in a slim compact form factor.', 'Editor pick', 21),
('xiaomi-22-5w-power-bank-10000mah-lite', 'latest-finds', 'Latest finds', 'The safest overall under-₱1,000 pick for most Filipino buyers: known brand, useful 22.5W class output, 10,000mAh daily-carry capacity, and broad marketplace availability.', 'Editor pick', 22),
('epson-ecotank-l3250', 'latest-finds', 'Latest finds', 'The best overall student printer because it combines low ink cost, print-scan-copy functions, and WiFi printing for phones, laptops, and shared family use.', 'Editor pick', 23),
('nitecore-p10i-1800-lumen-usb-c-rechargeable-flashlight', 'latest-finds', 'Latest finds', 'The best overall rechargeable flashlight for the Philippines — Nitecore P10i delivers 1800 lumens of genuine rated brightness, USB-C quick charging from any power bank, IPX8 waterproofing for Philippine rain, and 5 output modes that cover every Filipino use case from bedroom brownout to Bataan hiking.', 'Editor pick', 24),
('kyowa-kw-1327-rice-cooker', 'home', 'Home', 'The most ubiquitous rice cooker in Philippine households for a reason — Kyowa''s basic rice cookers deliver reliable everyday kanin cooking at the lowest possible price, with enough Philippine brand support to find service when needed.', 'Home pick', 25),
('hanabishi-hhrc-6fs-mini-rice-cooker', 'home', 'Home', 'The safest overall under-₱1,000 rice cooker for students and solo renters because it combines a familiar local brand, small capacity, and practical price.', 'Home pick', 26),
('dreame-d9-robot-vacuum-and-mop', 'home', 'Home', 'The best all-around value in the mid-range — LiDAR mapping, simultaneous vacuuming and mopping, and a strong price for the feature set.', 'Home pick', 27),
('moen-engage-3-mode-shower-head', 'latest-finds', 'Latest finds', 'The best shower head for Philippine low water pressure situations — Moen''s focused spray modes maximize perceived pressure from low-flow supply, with Moen''s internationally recognized quality and lifetime guarantee policy.', 'Editor pick', 28),
('kyowa-kw-1509-slow-cooker', 'latest-finds', 'Latest finds', 'Kyowa''s 4L slow cooker adds keep-warm function and a slightly more robust build over the basic Hanabishi entry — the recommended budget upgrade for Filipino households that want the keep-warm feature for serving flexibility.', 'Editor pick', 29),
('oppo-band-2', 'latest-finds', 'Latest finds', 'The best entry-level fitness band for OPPO and Realme users — OPPO Band 2 delivers core health tracking and smart notifications in a premium design at the lowest price point among reputable brands with Philippine presence.', 'Editor pick', 30),
('apc-performance-surgearrest-6-outlet-230v', 'latest-finds', 'Latest finds', 'The safer APC direction for Philippine buyers — look for 230V SurgeArrest models sold by local retailers instead of importing 120V US-only strips.', 'Editor pick', 31),
('xiaomi-pad-7', 'latest-finds', 'Latest finds', 'The best Android value tablet for buyers who want smooth performance, a large screen, and strong specs without iPad pricing.', 'Editor pick', 32),
('soundcore-r50i-nc', 'latest-finds', 'Latest finds', 'The safest under-₱2,000 true wireless earbud for most Filipino buyers because it combines ANC, app support, water resistance, a practical case, and official Philippine availability.', 'Editor pick', 33),
('asahi-wd-888-hot-and-cold-water-dispenser', 'home', 'Home', 'The best budget water dispenser in the Philippines — Asahi hot and cold dispensers provide reliable compressor-cooled cold water and quick-heat hot water at the lowest price from a recognizable Philippine appliance brand.', 'Home pick', 34),
('belo-essentials-whitening-body-soap', 'latest-finds', 'Latest finds', 'The best overall whitening soap for the Philippines — Belo Essentials combines multiple proven whitening actives (kojic acid, salicylic acid, niacinamide) under the most trusted Filipino dermatological brand, delivering comprehensive whitening at a moderate ₱120–₱200 price.', 'Editor pick', 35),
('qcy-t13-true-wireless-earbuds', 'latest-finds', 'Latest finds', 'The best wireless earbuds under ₱900 in the Philippines — QCY T13 delivers 30-hour total battery life, IPX4 water resistance, and balanced audio with good bass for Filipino music preferences at the lowest competitive price from a reputable audio brand.', 'Editor pick', 36),
('redmi-buds-6-play', 'latest-finds', 'Latest finds', 'The Xiaomi ecosystem pick for buyers who want a current Redmi budget earbud instead of random ultra-cheap TWS.', 'Editor pick', 37),
('philips-essential-air-fryer-hd9200', 'home', 'Home', 'The most established brand pick in this guide — Philips'' HD9200 combines a 4.1L pan, 1400W power, adjustable time and temperature control, and Philips Rapid Air design in a simple mid-premium package.', 'Home pick', 38),
('levoit-core-300', 'home', 'Home', 'The best overall bedroom air purifier for Philippine households — Levoit''s Core 300 combines a 3-stage H13 True HEPA filter, ultra-quiet sleep mode (24dB), and interchangeable filter options into a compact form that excels in bedroom use.', 'Home pick', 39),
('dream-mate-polar-fleece-blanket-80x90in', 'latest-finds', 'Latest finds', 'The better budget choice if you want actual body coverage without jumping to comforter prices.', 'Editor pick', 40),
('infinix-smart-10', 'latest-finds', 'Latest finds', 'The Infinix entry option for buyers who want a new budget phone and like Infinix''s spec-value approach.', 'Editor pick', 41),
('philips-led-eyecomfort-desk-lamp', 'for-your-desk', 'For your desk', 'The best branded eye-comfort route for parents buying a study lamp, especially when the student reads printed books or writes for long periods.', 'Desk pick', 42),
('tefal-optigrill', 'latest-finds', 'Latest finds', 'The best premium electric grill for serious Filipino indoor grilling — Tefal''s OptiGrill uses automatic thickness measurement and color-coded doneness indicators to grill chicken, pork, fish, and burgers to precisely the right internal temperature without guessing or cutting open to check.', 'Editor pick', 43),
('midea-2-burner-induction-cooker', 'latest-finds', 'Latest finds', 'The best dual induction cooker for Filipino households — Midea''s 2-burner induction delivers simultaneous induction cooking efficiency with precise digital control at competitive pricing, making it the best value for Filipino condo dwellers with a magnetic cookware collection.', 'Editor pick', 44),
('asahi-extension-cord-with-individual-switches', 'latest-finds', 'Latest finds', 'The best budget extension cord for Filipino households — Asahi is a widely trusted Philippine-distributed electrical brand with certifications, available in every Filipino hardware store, providing reliable basic protection at the lowest trustworthy price point.', 'Editor pick', 45),
('black-diamond-spot-400-headlamp', 'for-your-desk', 'For your desk', 'The best outdoor-oriented headlamp for camping, hiking, travel, and serious rainy-season backup.', 'Desk pick', 46),
('fantech-hg22-fusion-gaming-headset', 'latest-finds', 'Latest finds', 'The best gaming headset from a Philippines-native gaming brand — Fantech HG22 Fusion delivers 50mm drivers, an omnidirectional microphone, and Fantech''s Filipino market expertise at the same price as budget generic alternatives.', 'Editor pick', 47),
('panasonic-eh-hv10-nanoe-straightener', 'home', 'Home', 'The best recognized international brand hair straightener under ₱1,400 for the Philippines — Panasonic''s Nanoe technology emits water particles that moisturize Filipino hair while straightening, addressing the dryness that thermal styling creates in Philippine conditions.', 'Home pick', 48),
('hanabishi-hand-mixer', 'latest-finds', 'Latest finds', 'The most affordable route to Filipino home baking — Hanabishi hand mixers are available at every appliance store, reliable for casual use, and deliver adequate performance for eggs, cream, and cake batter.', 'Editor pick', 49),
('bostik-1l-super-vulcaseal', 'home', 'Home', 'A roof and gutter patch option for smaller accessible leak points.', 'Home pick', 50),
('imarflex-imc-122ds-6-in-1-multi-cooker', 'latest-finds', 'Latest finds', 'The best compact plug-in pick for small households that want a multi-use cooker rather than a single-purpose hot pot.', 'Editor pick', 51),
('tomtoc-360-protective-laptop-case', 'gifts-that-dont-feel-generic', 'Gifts that don’t feel generic', 'The best laptop case for maximum drop and scratch protection under ₱1,500 — Tomtoc''s 360-degree cushioning system, reinforced corner protection, and CornerArmor technology provides the most complete laptop protection available at this price point for the Filipino commuter navigating crowded MRT cars and office corridors.', 'Giftable', 52),
('samsung-ms23k3513ak-solo-microwave', 'latest-finds', 'Latest finds', 'The best mid-range solo microwave for Filipino households — Samsung''s MS23K3513AK delivers 800W, a 23L ceramic enamel interior, digital display, and pre-programmed cooking menus in one of the most complete mid-range packages available in the Philippines.', 'Editor pick', 53),
('flowtron-bk-40d-electronic-bug-zapper', 'latest-finds', 'Latest finds', 'The best outdoor mosquito and flying insect killer for large Philippine outdoor areas — Flowtron BK-40D''s 1.5-acre coverage, durable UV bulb, and chemical-free operation makes it ideal for Philippine houses with gardens, outdoor dining areas, and commercial outdoor settings during dengue season.', 'Editor pick', 54),
('jbl-clip-4-waterproof-bluetooth-speaker', 'latest-finds', 'Latest finds', 'The best waterproof clip speaker for Filipino travelers and beach-goers — JBL Clip 4''s IP67 waterproofing, integrated carabiner clip, and compact pocketable size make it the most practical outdoor companion for Philippine island hopping and beach trips.', 'Editor pick', 55),
('baseus-bipow-power-bank-20000mah', 'latest-finds', 'Latest finds', 'The best feature-to-price power bank available in the Philippines — 20,000mAh high capacity with 22W dual fast charging at a price that most Filipino buyers can afford on a single payroll.', 'Editor pick', 56),
('ugreen-10000mah-22-5w-power-bank', 'latest-finds', 'Latest finds', 'A strong USB-C value pick when vouchers keep it under ₱1,000, especially for users who want a cleaner accessory brand and more confidence than random low-price listings.', 'Editor pick', 57),
('epson-ecotank-l3210', 'latest-finds', 'Latest finds', 'The best value ink tank if WiFi is not required, with low ink cost and all-in-one functions at a lower price than wireless EcoTank models.', 'Editor pick', 58),
('fenix-e35r-3000-lumen-usb-c-rechargeable-flashlight', 'latest-finds', 'Latest finds', 'The brightest rechargeable flashlight at a practical Philippine price point — Fenix E35R''s 3000 lumens of actual rated output illuminates distances impossible with most consumer flashlights, with Fenix''s premium build quality, USB-C charging, and IPX8 waterproofing for demanding Philippine outdoor conditions.', 'Editor pick', 59),
('zojirushi-nl-aac05-neuro-fuzzy-rice-cooker', 'home', 'Home', 'The best rice cooker in the world for the Filipino market — Zojirushi''s Neuro Fuzzy technology produces the most consistently perfect kanin of any cooker available, with settings optimized for every rice variety Filipinos eat.', 'Home pick', 60),
('kyowa-kw-2016-mini-rice-cooker', 'home', 'Home', 'A strong trusted-brand mini cooker if you want a Philippine appliance brand and can catch it below the ₱1,000 ceiling.', 'Home pick', 61),
('ecovacs-deebot-n8', 'home', 'Home', 'The best choice for homes with complex layouts, lots of furniture, or families with children who leave things on the floor.', 'Home pick', 62),
('grohe-tempesta-100-rain-shower-head', 'latest-finds', 'Latest finds', 'The best overall shower head for the Philippines — Grohe Tempesta 100 delivers the genuine luxury rain shower experience with German engineering quality, SpeedClean anti-limescale silicone nozzles (critical for Philippine hard water), and a spray pattern broad enough to transform the Filipino morning shower.', 'Editor pick', 63),
('xiaomi-smart-band-8-pro', 'latest-finds', 'Latest finds', 'The best all-around fitness band for Filipino buyers — Xiaomi Smart Band 8 Pro delivers a 1.74-inch rectangular AMOLED display, comprehensive health sensors, and 150+ workout modes in a premium wristband form factor that competes with smartwatches at a fraction of the price.', 'Editor pick', 64),
('samsung-galaxy-tab-s10-fe', 'latest-finds', 'Latest finds', 'The best Android student and note-taking tablet if you want Samsung software, S Pen support, and a stronger tablet ecosystem.', 'Editor pick', 65),
('realme-buds-t310', 'latest-finds', 'Latest finds', 'The best under-₱2,000 pick when calls, stronger ANC, and Android phone integration matter more than the lowest possible price.', 'Editor pick', 66),
('hanabishi-hwd-3800-hot-and-cold-water-dispenser', 'home', 'Home', 'The most popular water dispenser brand in the Philippines — Hanabishi hot and cold dispensers balance price, performance, and brand reliability for the standard Filipino household water setup, with nationwide service support and universal gallon compatibility.', 'Home pick', 67),
('realme-buds-air-3-neo', 'latest-finds', 'Latest finds', 'The best wireless earbuds under ₱1,200 for voice calls and WFH use in the Philippines — Realme Buds Air 3 Neo''s AI ENC call noise reduction delivers clearer call audio for Philippine WFH meetings, Viber calls, and noisy commute conversations.', 'Editor pick', 68),
('baseus-bowie-wm02', 'latest-finds', 'Latest finds', 'The compact-case pick for buyers who want cheap, small, and easy-to-carry wireless earphones.', 'Editor pick', 69),
('kyowa-kw-3820af-2l-air-fryer', 'home', 'Home', 'The most affordable air fryer entry point for Filipino households from a recognizable local brand — Kyowa''s 2L air fryer delivers the core air frying experience (crispy bangus, pork chop, potato wedges) at ₱700–₱1,100 for single-person and couple households in Philippine condos and apartments.', 'Home pick', 70),
