('firefly-yellow-shield-air-purifier-with-mini-night-light-fyp102', 'home', 'Home', 'A practical local hardware-store option for small rooms if you prefer a listing with a checked Philippine retail price.', 'Home pick', 72),
('ikea-holmvi-throw', 'latest-finds', 'Latest finds', 'The best cheap, decent-looking throw for sofas, study chairs, and rainy-day naps.', 'Editor pick', 73),
('honor-x5c-plus', 'latest-finds', 'Latest finds', 'A HONOR entry option if you want a familiar brand alternative and the checkout price stays under ₱5,000.', 'Editor pick', 74),
('firefly-rechargeable-led-desk-lamp', 'for-your-desk', 'For your desk', 'The best practical choice for students in brownout-prone areas who need a lamp that still works when the outlet does not.', 'Desk pick', 75),
('hanabishi-electric-coil-stove', 'latest-finds', 'Latest finds', 'The most affordable electric stove from a trusted Philippine brand — Hanabishi''s coil electric stove provides a basic single or double-burner cooking surface for Filipino households making the LPG-to-electric switch at the most accessible entry price.', 'Editor pick', 76),
('xiaomi-mi-power-strip-with-usb-ports', 'latest-finds', 'Latest finds', 'The best extension cord for Filipino WFH setups and tech-heavy desks — Xiaomi Mi Power Strip''s combination of AC outlets and USB-A/USB-C fast charging ports eliminates the cable clutter of multiple phone chargers in the typical Filipino tech household.', 'Editor pick', 77),
('fenix-hm50r-headlamp', 'for-your-desk', 'For your desk', 'The best rugged premium headlamp for users who want stronger construction and more serious outdoor reliability.', 'Desk pick', 78),
('redragon-h510-zeus-gaming-headset', 'latest-finds', 'Latest finds', 'The best gaming headset for immersive audio and 7.1 virtual surround under ₱1,400 — Redragon H510 Zeus''s 53mm drivers and USB-powered 7.1 surround deliver the most realistic positional audio for FPS games among budget headsets.', 'Editor pick', 79),
('remington-s1370-tourmaline-ceramic-straightener', 'home', 'Home', 'The best versatile styling tool under ₱1,800 — Remington S1370''s tourmaline ceramic plates provide ionic conditioning for Philippine humidity control while the plate shape allows both straightening and loose-wave curling, making it a dual-purpose styling tool for Filipino working women.', 'Home pick', 80),
('kyowa-hand-mixer', 'latest-finds', 'Latest finds', 'The best overall local brand hand mixer — Kyowa balances build quality, motor performance, and price better than most budget competitors, with 5–7 speed settings and reliable consistent performance.', 'Editor pick', 81),
('bostik-300ml-super-vulcaseal-sealant', 'home', 'Home', 'A cartridge option for small seams and joints where the product''s instructions are suitable.', 'Home pick', 82),
('imarflex-irc-18l-10-cup-4-in-1-multi-cooker', 'latest-finds', 'Latest finds', 'A good crossover pick if you want rice-cooker usefulness plus soup and hot pot-style cooking.', 'Editor pick', 83),
('swissgear-tech-15-6-inch-laptop-backpack', 'gifts-that-dont-feel-generic', 'Gifts that don’t feel generic', 'The best commuter laptop backpack under ₱1,500 for Filipinos using MRT, LRT, and jeepney daily — SwissGear provides maximum organizational capacity, ergonomic back panel, and a design evolved specifically for tech commuters who carry laptop, charger, cables, and daily essentials in one organized bag.', 'Giftable', 84),
('panasonic-nn-st27hbpq-solo-microwave', 'latest-finds', 'Latest finds', 'The best premium solo microwave in the Philippines — Panasonic''s 27L NN-ST27H brings inverter technology for smooth, even heating without the power cycling that overcooks edges while leaving the center cold, in the largest cavity among the solo options in this guide.', 'Editor pick', 85),
('marshall-willen-bluetooth-speaker', 'latest-finds', 'Latest finds', 'The best portable speaker for Filipino buyers who want brand prestige and iconic design — Marshall Willen''s vintage guitar amplifier aesthetic, IP67 waterproofing, and 15-hour battery make it the most visually distinctive speaker at the top of the under-₱2,000 budget.', 'Editor pick', 86),
('anker-powercore-10000', 'latest-finds', 'Latest finds', 'The most trusted power bank brand in the world for a reason — Anker''s MultiProtect safety system and PowerIQ intelligent charging technology deliver consistent, safe charging over hundreds of cycles with industry-leading quality control.', 'Editor pick', 87),
('baseus-airpow-10000mah-20w', 'latest-finds', 'Latest finds', 'The best slim budget pick for users who want a recognizable accessory brand, 20W class charging, and a power bank that does not feel huge in a school or work bag.', 'Editor pick', 88),
('canon-pixma-g3020', 'latest-finds', 'Latest finds', 'The best student pick for color-heavy projects, photo-heavy reports, and families that want wireless refillable-ink printing with Canon color output.', 'Editor pick', 89),
('black-diamond-spot-350-rechargeable-headlamp', 'latest-finds', 'Latest finds', 'The best rechargeable headlamp for Filipino hikers and emergency preparation — Black Diamond Spot 350 provides hands-free lighting for cooking, packing, evacuation, and trail hiking, with IP67 waterproofing rated for Philippine monsoon conditions.', 'Editor pick', 90),
('tough-mama-0-6l-rice-cooker', 'home', 'Home', 'A practical dorm-value cooker for students who want a small appliance with familiar branding and simple daily rice cooking.', 'Home pick', 91),
('lefant-m210-robot-vacuum', 'home', 'Home', 'The most affordable robot vacuum that actually works — ideal for small, open floor plans with tile or hardwood and no complex furniture arrangements.', 'Home pick', 92),
('hansgrohe-croma-100-4-jet-shower-head', 'latest-finds', 'Latest finds', 'The best premium rainfall shower head for Filipino bathroom renovations — Hansgrohe Croma 100''s 4-jet spray modes, QuickClean anti-limescale technology, and German premium quality deliver the hotel-bathroom shower experience for the discerning Filipino homeowner.', 'Editor pick', 93),
('huawei-band-8', 'latest-finds', 'Latest finds', 'The best health-monitoring fitness band under ₱3,000 for Filipino users — Huawei Band 8''s comprehensive TruSeen heart rate and TruSleep analysis provide the most medically-oriented health data of any wearable at this price point.', 'Editor pick', 94),
('samsung-galaxy-tab-a9-plus', 'latest-finds', 'Latest finds', 'The best affordable Samsung tablet for families who want a known brand, local support, and basic Android tablet use.', 'Editor pick', 95),
('redmi-buds-6-lite', 'latest-finds', 'Latest finds', 'The easiest Xiaomi-family ANC pick under ₱2,000, especially if you already use a Xiaomi, Redmi, or POCO phone.', 'Editor pick', 96),
('kyowa-kw-1500-hot-cold-and-normal-water-dispenser', 'home', 'Home', 'The best water dispenser for Filipino households wanting hot, normal (room temperature), and cold functions — Kyowa''s 3-temperature dispensers include a normal water faucet that saves electricity when room-temperature water is preferred, particularly during cooler months.', 'Home pick', 97),
('xiaomi-redmi-buds-4-lite', 'latest-finds', 'Latest finds', 'The best wireless earbuds for Xiaomi ecosystem users under ₱1,200 — Xiaomi Redmi Buds 4 Lite integrates with Mi Fitness and Xiaomi phones for seamless connectivity, with solid audio tuning and Xiaomi''s trusted brand reliability.', 'Editor pick', 98),
('oppo-enco-buds2', 'latest-finds', 'Latest finds', 'The OPPO/Android sale pick if you can catch it at ₱1,000 or less from a reliable seller.', 'Editor pick', 99),
('hanabishi-hraf-28s-3l-air-fryer', 'home', 'Home', 'The best 3L Philippine local brand air fryer for families of 2–3 — Hanabishi''s HRAF-28S brings a larger 3L basket and better temperature control than 2L budget alternatives at a price that serves as the mid-range local brand option for Filipino households upgrading from basic cooking methods.', 'Home pick', 100)
) as batch(slug, collection, collection_title, editorial_blurb, badge, batch_order)
join "thebudolfinds".products product on product.slug=batch.slug
left join lateral (select max(collection_order) max_order from "thebudolfinds".homepage_feed_items where collection=batch.collection) feed on true
on conflict (collection, product_id) do update set collection_title=excluded.collection_title, editorial_blurb=excluded.editorial_blurb, badge=excluded.badge, is_active=true, updated_at=now();
